const encoder=new TextEncoder();
function crc32(bytes){let crc=-1;for(const byte of bytes){crc^=byte;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}return (crc^-1)>>>0;}
export function zip(files){const local=[],central=[];let offset=0;for(const [path,value] of Object.entries(files)){const name=encoder.encode(path),data=typeof value==='string'?encoder.encode(value):value,crc=crc32(data),head=new Uint8Array(30+name.length),v=new DataView(head.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);head.set(name,30);local.push(head,data);const ch=new Uint8Array(46+name.length),c=new DataView(ch.buffer);c.setUint32(0,0x02014b50,true);c.setUint16(4,20,true);c.setUint16(6,20,true);c.setUint16(8,0x800,true);c.setUint32(16,crc,true);c.setUint32(20,data.length,true);c.setUint32(24,data.length,true);c.setUint16(28,name.length,true);c.setUint32(42,offset,true);ch.set(name,46);central.push(ch);offset+=head.length+data.length;}const centralSize=central.reduce((n,a)=>n+a.length,0),end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,central.length,true);e.setUint16(10,central.length,true);e.setUint32(12,centralSize,true);e.setUint32(16,offset,true);const out=new Uint8Array(offset+centralSize+22);let pos=0;for(const a of [...local,...central,end]){out.set(a,pos);pos+=a.length;}return out;}
export function decodeData(url){return Uint8Array.from(atob(url.split(',')[1]),c=>c.charCodeAt(0));}
